#!/bin/bash
# Re-measure the M1 / M4 / M5 / accuracy-pass synthetic metrics on the current tree (hfbox).
# setup: mkdir -p _m && cp docs/evidence/M4/eval/*.py docs/evidence/M4/eval/*.sh _m/
# usage (from the copy root): bash _m/run_metrics.sh <step>   step: gen | gt | yolo | vit | mot
# then: python _m/agg.py _m/out > metrics_all.json
# Synthetic only: every clip is generated by `courtcam synth` (labelled synthetic).
source /workspace/wt/replay-env/env.sh
exec < /dev/null  # `timeout` backgrounds its child: ffmpeg reading the tty would stop it (SIGTTIN)
d=$(pwd)
export PYTHONPATH=$d/courtcam:$d/services/api:$d/services/worker:$d/render
export HF_HOME=/workspace/wt/replay-env/hf HF_HUB_OFFLINE=1
export COURTCAM_POSE_MODEL=/workspace/wt/replay-env/models/yolo/yolo11m-pose.pt
CLIPS="basketball_half_s7 basketball_half_s11 basketball_full_s7 badminton_doubles_s7 badminton_doubles_s11 pickleball_doubles_s7 pickleball_doubles_s11 volleyball_indoor_s7 volleyball_indoor_s11"
S=_m/synth O=_m/out
mkdir -p $S $O
case $1 in
gen)  # 90 s clips, 1280x720 30 fps (synth defaults), seeds 7 / 11
  for c in $CLIPS; do
    IFS=_ read -r sport variant seed <<< "$c"
    [ -f $S/$c/clip.mp4 ] && continue
    flock /workspace/wt/replay-env/.cpu.lock python -m courtcam.cli synth --out $S/$c --sport $sport \
      --variant $variant --duration 90 --seed ${seed#s} --voice-dir samples/synthetic/voice 2>&1 | tail -1
  done ;;
gt)   # synthetic (GT) detector + GT poses, then triggers with whisper-small + simulated roster
  for c in $CLIPS; do
    out=$O/${c}_gt; rm -rf "${out:?}"
    flock /workspace/wt/replay-env/.cpu.lock python _m/run1.py $S/$c $out synthetic auto > $out.times.json 2> $out.log || { echo "FAIL $c"; tail -3 $out.log; continue; }
    flock /workspace/airtools/.gpu.lock timeout 600 python _m/run_trig.py $S/$c $out openai/whisper-small > $out.trig.json 2>> $out.log
    python _m/eval_synth.py $S/$c $out > $out.eval.json 2>> $out.log || echo "EVALFAIL $c"
    echo "done gt $c"
  done ;;
yolo) # YOLO detect + YOLO pose (default pipeline), triggers with whisper-small
  for c in $CLIPS; do
    out=$O/${c}_yolo; rm -rf "${out:?}"
    flock /workspace/airtools/.gpu.lock timeout 900 python _m/run1.py $S/$c $out yolo yolo > $out.times.json 2> $out.log || { echo "FAIL $c"; tail -3 $out.log; continue; }
    flock /workspace/airtools/.gpu.lock timeout 600 python _m/run_trig.py $S/$c $out openai/whisper-small > $out.trig.json 2>> $out.log
    python _m/eval_synth.py $S/$c $out > $out.eval.json 2>> $out.log || echo "EVALFAIL $c"
    echo "done yolo $c"
  done ;;
vit)  # same YOLO tracks, pose -> plays re-run with ViTPose (--pose vit)
  for c in $CLIPS; do
    out=$O/${c}_vit
    flock /workspace/airtools/.gpu.lock timeout 900 python _m/rerun.py $O/${c}_yolo $out vit --model /workspace/wt/replay-env/models/vitpose/vitpose-base-simple > $out.times.json 2> $out.log || { echo "FAIL $c"; tail -3 $out.log; continue; }
    python _m/eval_synth.py $S/$c $out > $out.eval.json 2>> $out.log || echo "EVALFAIL $c"
    echo "done vit $c"
  done ;;
mot)  # CLEAR-MOT / IDF1 (courtcam eval) on the five s7 scenes, YOLO and GT detector
  for c in basketball_half_s7 basketball_full_s7 pickleball_doubles_s7 badminton_doubles_s7 volleyball_indoor_s7; do
    for t in yolo gt; do
      python -m courtcam.cli eval --gt $S/$c/ground_truth.json --out $O/${c}_$t --json $O/${c}_$t.mot.json > /dev/null || echo "MOTFAIL $c $t"
    done
  done; echo done mot ;;
esac
